software OnlineShop {
  metadata { displayName "OnlineShop"; namespace "example.multiplication"; }
  target { language java 21; framework spring_boot; persistence mybatis_plus; database mysql; build maven; interface rest; }
  sources { }
  imports { }
  declarations {
    enum Role { CUSTOMER, ADMIN }
    enum OrderState { CREATED, PAID, SHIPPED, CANCELLED }
    enum ProductState { ON_SHELF, OFF_SHELF }

    type UnitPrice = Money where precision(21, 4), min(0);
    type TotalAmount = Money where precision(19, 2), min(0);

    error BadPage http 400;
    error InvalidWindow http 400;
    error Missing http 404;
    error OrderNotFound http 404;
    error ProductNotFound http 404;
    error RoomMissing http 404;
    error CartItemNotFound http 404;
    error CouponNotFound http 404;
    error Forbidden http 403;
    error NotYourOrder http 403;
    error AlreadyInCart http 409;
    error CartEmpty http 409;
    error CartTooLarge http 409;
    error CouponAlreadyUsed http 409;
    error CouponCodeTaken http 409;
    error CouponExhausted http 409;
    error CouponExpired http 409;
    error Full http 409;
    error InconsistentOrder http 409;
    error MinSpendNotMet http 409;
    error NotCancellable http 409;
    error NotPayable http 409;
    error NotShippable http 409;
    error OrderTooLarge http 409;
    error OutOfStock http 409;
    error StockLimit http 409;
    error TooManyWeeks http 409;

    entity User persistent {
      identity id: Id generated auto;
      field role: Role default Role.CUSTOMER;
      field name: Name unique;
      field passwordHash: Secret;
    }

    entity AccessToken persistent {
      identity id: Token generated uuid;
      field owner: Ref<User>;
      field expiresAt: Moment;
      credential subject owner expires expiresAt;
    }

    entity RefreshToken persistent {
      identity id: Token generated uuid;
      field owner: Ref<User>;
      field used: Flag default false;
      field expiresAt: Moment;
    }

    entity TokenPair persistent {
      identity id: Id generated auto;
      field accessToken: Token;
      field accessExpiresAt: Moment;
      field refreshToken: Token;
      field refreshExpiresAt: Moment;
    }

    entity ShopProduct persistent {
      identity id: Id generated auto;
      field name: Name;
      field description: Optional<Text>;
      field price: TotalAmount;
      field stock: Count;
      field state: ProductState default ProductState.ON_SHELF;
    }

    entity PurchaseOrder persistent {
      identity id: Id generated auto;
      field buyer: Ref<User>;
      field state: OrderState default OrderState.CREATED;
      field total: TotalAmount;
      field createdAt: Moment;
    }

    entity OrderLine persistent {
      identity id: Id generated auto;
      field purchase: Ref<PurchaseOrder>;
      field product: Ref<ShopProduct>;
      field quantity: Quantity;
      field unitPrice: TotalAmount;
    }

    entity CartItem persistent {
      identity id: Id generated auto;
      field owner: Ref<User>;
      field product: Ref<ShopProduct>;
      field quantity: Quantity;
      unique (owner, product);
    }

    entity Coupon persistent {
      identity id: Id generated auto;
      field code: Code unique;
      field amountOff: TotalAmount;
      field minSpend: TotalAmount;
      field startsAt: Moment;
      field endsAt: Moment;
      field totalLimit: Count;
      field used: Count default 0;
    }

    entity Redemption persistent {
      identity id: Id generated auto;
      field coupon: Ref<Coupon>;
      field buyer: Ref<User>;
      field purchase: Ref<PurchaseOrder>;
      field amountOff: TotalAmount;
      unique (coupon, buyer);
      unique (purchase, buyer);
    }

    entity Calculation persistent {
      identity id: Id generated auto;
      field amount: TotalAmount;
      field count: Count;
      field wide: Serial;
    }

    entity Product persistent {
      identity id: Id generated auto;
      field price: UnitPrice;
      field stock: Count;
    }

    entity Receipt persistent {
      identity id: Id generated auto;
      field product: Ref<Product>;
      field total: TotalAmount;
      field quantity: Quantity;
    }

    entity ReceiptLine persistent {
      identity id: Id generated auto;
      field receipt: Ref<Receipt>;
      field quantity: Quantity;
      field unitPrice: UnitPrice;
    }

    entity Course persistent {
      identity id: Id generated auto;
      field capacity: Quantity;
      field enrolled: Count default 0;
    }

    entity Room persistent {
      identity id: Id generated auto;
      field name: Name unique;
    }

    entity Booking persistent {
      identity id: Id generated auto;
      field room: Ref<Room>;
      field startsAt: Moment;
      field endsAt: Moment;
    }

    input RegisterInput {
      field name: Name where length(1, 64);
      field password: Secret;
    }

    input LoginInput {
      field name: Name where length(1, 64);
      field password: Secret;
    }

    input RefreshInput {
      field refreshToken: Token;
    }

    input LogoutInput {
      field refreshToken: Token;
    }

    input AddProductInput {
      field name: Name where length(1, 64);
      field description: Optional<Text>;
      field price: TotalAmount;
      field stock: Count;
    }

    input SearchProductsInput {
      field keyword: Text where notBlank;
      field page: PageNo;
      field size: PageSize;
    }

    input BuyNowInput {
      field productId: Id;
      field quantity: Quantity;
    }

    input AddToCartInput {
      field productId: Id;
      field quantity: Quantity;
    }

    input ChangeCartQuantityInput {
      field id: Id;
      field quantity: Quantity;
    }

    input RemoveFromCartInput {
      field id: Id;
    }

    input MyCartInput {
      field page: PageNo;
      field size: PageSize;
    }

    input ClearCartInput { }

    input CheckoutInput { }

    input AddCouponInput {
      field code: Code where length(1, 64);
      field amountOff: TotalAmount;
      field minSpend: TotalAmount;
      field startsAt: Moment;
      field endsAt: Moment;
      field totalLimit: Count;
    }

    input ApplyCouponInput {
      field orderId: Id;
      field code: Code where length(1, 64);
    }

    input PayInput {
      field id: Id;
    }

    input ShipInput {
      field id: Id;
    }

    input CancelOrderInput {
      field id: Id;
    }

    input MyOrdersInput {
      field page: PageNo;
      field size: PageSize;
    }

    input OrderLinesInput {
      field orderId: Id;
      field page: PageNo;
      field size: PageSize;
    }

    input MultiplyInput {
      field price: UnitPrice;
      field quantity: Count;
      field left: Count;
      field right: Count;
      field wide: Serial;
    }

    input WideInput {
      field price: UnitPrice;
      field quantity: Count;
      field left: Count;
      field right: Count;
      field wide: Serial;
    }

    input ReverseInput {
      field price: UnitPrice;
      field quantity: Count;
      field left: Count;
      field right: Count;
      field wide: Serial;
    }

    input PurchaseProductInput {
      field id: Id;
      field quantity: Quantity;
    }

    input EnrollCourseInput {
      field id: Id;
    }

    input ShowCourseInput {
      field id: Id;
    }

    input ShowProductInput {
      field id: Id;
    }

    input BookInput {
      field roomId: Id;
      field startsAt: Moment;
      field endsAt: Moment;
    }

    input BookWeeklyInput {
      field roomId: Id;
      field startsAt: Moment;
      field endsAt: Moment;
      field weeks: Count;
    }

    input BookAfterReadInput {
      field roomId: Id;
      field startsAt: Moment;
      field endsAt: Moment;
    }

    view UserView from User {
      field id: Id;
      field name: Name;
      field role: Role;
    }

    view ShopProductView from ShopProduct {
      field id: Id;
      field name: Name;
      field description: Optional<Text>;
      field price: TotalAmount;
      field stock: Count;
      field state: ProductState;
    }

    view ShopProductShowView from ShopProduct {
      field id: Id;
      field price: TotalAmount;
      field stock: Count;
      field inventoryValue: UnitPrice = item.price * item.stock;
      field soldOut: Flag = item.stock == 0;
    }

    view OrderView from PurchaseOrder {
      field id: Id;
      field state: OrderState;
      field total: TotalAmount;
      field createdAt: Moment;
    }

    view OrderLineView from OrderLine {
      field id: Id;
      field product: Ref<ShopProduct>;
      field quantity: Quantity;
      field unitPrice: TotalAmount;
    }

    view CartItemView from CartItem {
      field id: Id;
      field product: Ref<ShopProduct>;
      field quantity: Quantity;
    }

    view CouponView from Coupon {
      field id: Id;
      field code: Code;
      field amountOff: TotalAmount;
      field minSpend: TotalAmount;
      field startsAt: Moment;
      field endsAt: Moment;
      field totalLimit: Count;
      field used: Count;
    }

    view CalculationView from Calculation {
      field id: Id;
      field amount: TotalAmount;
      field count: Count;
      field wide: Serial;
    }

    view ReceiptView from Receipt {
      field id: Id;
      field total: TotalAmount;
      field quantity: Quantity;
      field doubledTotal: TotalAmount = item.total * 2;
    }

    view CourseView from Course {
      field id: Id;
      field capacity: Quantity;
      field enrolled: Count;
      field remaining: Count = item.capacity - item.enrolled;
      field full: Flag = item.capacity - item.enrolled == 0;
    }

    view BookingView from Booking {
      field id: Id;
      field startsAt: Moment;
      field endsAt: Moment;
    }

    capability Register {
      input RegisterInput;
      output UserView;
      fails Missing;
      requires atomic;
      expose command at "/register";
      workflow {
        validate input.name is present else Missing;
        exists User where item.name == input.name as found;
        validate not found else Missing;
        create User as made { name: input.name; passwordHash: input.password; role: Role.CUSTOMER; }
        persist made;
        return made;
      }
    }

    capability Login {
      input LoginInput;
      output TokenPair;
      fails Missing;
      requires atomic;
      expose command at "/login";
      workflow {
        load User by name: input.name as account else Missing;
        validate account.passwordHash matches input.password else Missing;
        create AccessToken as access { owner: account; expiresAt: now() + 15 minutes; }
        persist access;
        create RefreshToken as refresh { owner: account; used: false; expiresAt: now() + 7 days; }
        persist refresh;
        create TokenPair as pair { accessToken: access.id; accessExpiresAt: access.expiresAt; refreshToken: refresh.id; refreshExpiresAt: refresh.expiresAt; }
        persist pair;
        return pair;
      }
    }

    capability Refresh {
      input RefreshInput;
      output TokenPair;
      fails Missing;
      requires atomic;
      expose command at "/refresh";
      workflow {
        load RefreshToken by input.refreshToken as stored else Missing;
        validate stored.used == false else Missing;
        validate stored.expiresAt > now() else Missing;
        update stored { used: true; }
        persist stored;
        create AccessToken as access { owner: stored.owner; expiresAt: now() + 15 minutes; }
        persist access;
        create RefreshToken as refresh { owner: stored.owner; used: false; expiresAt: now() + 7 days; }
        persist refresh;
        create TokenPair as pair { accessToken: access.id; accessExpiresAt: access.expiresAt; refreshToken: refresh.id; refreshExpiresAt: refresh.expiresAt; }
        persist pair;
        return pair;
      }
    }

    capability Logout {
      input LogoutInput;
      output Unit;
      fails Missing;
      requires atomic;
      expose command at "/logout";
      workflow {
        load RefreshToken by input.refreshToken as stored else Missing;
        delete stored;
        return unit;
      }
    }

    capability AddProduct {
      actor Ref<User>;
      input AddProductInput;
      output ShopProductView;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command at "/products";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        create ShopProduct as made { name: input.name; description: input.description; price: input.price; stock: input.stock; state: ProductState.ON_SHELF; }
        persist made;
        return made;
      }
    }

    capability SearchProducts {
      input SearchProductsInput;
      output Page<ShopProductView>;
      fails BadPage;
      requires readonly;
      expose query at "/products";
      workflow {
        find ShopProduct where item.state == ProductState.ON_SHELF and item.name containsLiteral input.keyword order by name ascending, id ascending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability ShowProduct {
      input ShowProductInput;
      output ShopProductShowView;
      fails ProductNotFound;
      requires readonly;
      expose query at "/products/show";
      workflow {
        load ShopProduct by input.id as found else ProductNotFound;
        return found;
      }
    }

    capability BuyNow {
      actor Ref<User>;
      input BuyNowInput;
      output OrderView;
      fails OutOfStock;
      fails ProductNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders";
      workflow {
        load ShopProduct by input.productId as goods for update else ProductNotFound;
        validate goods.state == ProductState.ON_SHELF else ProductNotFound;
        update goods when goods.stock >= input.quantity else OutOfStock { stock: goods.stock - input.quantity; }
        persist goods;
        create PurchaseOrder as made { buyer: actor; state: OrderState.CREATED; total: goods.price * input.quantity; createdAt: now(); }
        persist made;
        create OrderLine as line { purchase: made; product: goods; quantity: input.quantity; unitPrice: goods.price; }
        persist line;
        return made;
      }
    }

    capability AddToCart {
      actor Ref<User>;
      input AddToCartInput;
      output CartItemView;
      fails AlreadyInCart;
      fails ProductNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/cart";
      workflow {
        load ShopProduct by input.productId as goods else ProductNotFound;
        validate goods.state == ProductState.ON_SHELF else ProductNotFound;
        exists CartItem where item.owner == actor and item.product == goods as found;
        validate not found else AlreadyInCart;
        create CartItem as made { owner: actor; product: goods; quantity: input.quantity; }
        persist made;
        return made;
      }
    }

    capability ChangeCartQuantity {
      actor Ref<User>;
      input ChangeCartQuantityInput;
      output CartItemView;
      fails CartItemNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/cart/{id}/quantity";
      workflow {
        load CartItem by input.id as row else CartItemNotFound;
        validate row.owner == actor else CartItemNotFound;
        update row { quantity: input.quantity; }
        persist row;
        return row;
      }
    }

    capability RemoveFromCart {
      actor Ref<User>;
      input RemoveFromCartInput;
      output Unit;
      fails CartItemNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/cart/{id}/remove";
      workflow {
        load CartItem by input.id as row else CartItemNotFound;
        validate row.owner == actor else CartItemNotFound;
        delete row;
        return unit;
      }
    }

    capability MyCart {
      actor Ref<User>;
      input MyCartInput;
      output Page<CartItemView>;
      fails BadPage;
      requires authenticated;
      requires readonly;
      expose query at "/cart";
      workflow {
        find CartItem where item.owner == actor order by id ascending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability ClearCart {
      actor Ref<User>;
      input ClearCartInput;
      output Unit;
      requires authenticated;
      requires atomic;
      expose command at "/cart/clear";
      workflow {
        each CartItem where item.owner == actor order by id ascending limit 100 else CartTooLarge as row {
          delete row;
        }
        return unit;
      }
    }

    capability Checkout {
      actor Ref<User>;
      input CheckoutInput;
      output OrderView;
      fails CartEmpty;
      fails CartTooLarge;
      fails OutOfStock;
      requires authenticated;
      requires atomic;
      expose command at "/cart/checkout";
      workflow {
        count CartItem where item.owner == actor as total;
        validate total > 0 else CartEmpty;
        validate total <= 50 else CartTooLarge;
        create PurchaseOrder as made { buyer: actor; state: OrderState.CREATED; total: 0.00; createdAt: now(); }
        persist made;
        each CartItem where item.owner == actor order by id ascending limit 50 else CartTooLarge as row {
          load ShopProduct by row.product as goods for update else ProductNotFound;
          validate goods.state == ProductState.ON_SHELF else ProductNotFound;
          update goods when goods.stock >= row.quantity else OutOfStock { stock: goods.stock - row.quantity; }
          persist goods;
          create OrderLine as line { purchase: made; product: goods; quantity: row.quantity; unitPrice: goods.price; }
          persist line;
          update made { total: made.total + goods.price * row.quantity; }
          delete row;
        }
        persist made;
        return made;
      }
    }

    capability AddCoupon {
      actor Ref<User>;
      input AddCouponInput;
      output CouponView;
      fails CouponCodeTaken;
      fails Forbidden;
      fails InvalidWindow;
      requires authenticated;
      requires atomic;
      expose command at "/coupons";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        validate input.startsAt < input.endsAt else InvalidWindow;
        exists Coupon where item.code == input.code as found;
        validate not found else CouponCodeTaken;
        create Coupon as made { code: input.code; amountOff: input.amountOff; minSpend: input.minSpend; startsAt: input.startsAt; endsAt: input.endsAt; totalLimit: input.totalLimit; used: 0; }
        persist made;
        return made;
      }
    }

    capability ApplyCoupon {
      actor Ref<User>;
      input ApplyCouponInput;
      output OrderView;
      fails CouponAlreadyUsed;
      fails CouponExhausted;
      fails CouponExpired;
      fails CouponNotFound;
      fails MinSpendNotMet;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{orderId}/coupon";
      workflow {
        load PurchaseOrder by input.orderId as order for update else OrderNotFound;
        validate order.buyer == actor else NotYourOrder;
        validate order.state == OrderState.CREATED else MinSpendNotMet;
        load Coupon by code: input.code as coupon for update else CouponNotFound;
        validate coupon.startsAt <= now() else CouponExpired;
        validate coupon.endsAt > now() else CouponExpired;
        validate order.total >= coupon.minSpend else MinSpendNotMet;
        validate order.total >= coupon.amountOff else MinSpendNotMet;
        validate coupon.used < coupon.totalLimit else CouponExhausted;
        exists Redemption where item.coupon == coupon and item.buyer == actor as used;
        validate not used else CouponAlreadyUsed;
        exists Redemption where item.purchase == order and item.buyer == actor as claimed;
        validate not claimed else CouponAlreadyUsed;
        update coupon { used: coupon.used + 1; }
        persist coupon;
        update order { total: order.total - coupon.amountOff; }
        persist order;
        create Redemption as made { coupon: coupon; buyer: actor; purchase: order; amountOff: coupon.amountOff; }
        persist made;
        return order;
      }
    }

    capability Pay {
      actor Ref<User>;
      input PayInput;
      output OrderView;
      fails NotPayable;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/pay";
      workflow {
        load PurchaseOrder by input.id as order for update else OrderNotFound;
        validate order.buyer == actor else NotYourOrder;
        update order when order.state == OrderState.CREATED else NotPayable { state: OrderState.PAID; }
        persist order;
        return order;
      }
    }

    capability Ship {
      actor Ref<User>;
      input ShipInput;
      output OrderView;
      fails Forbidden;
      fails NotShippable;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/ship";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load PurchaseOrder by input.id as order for update else OrderNotFound;
        update order when order.state == OrderState.PAID else NotShippable { state: OrderState.SHIPPED; }
        persist order;
        return order;
      }
    }

    capability CancelOrder {
      actor Ref<User>;
      input CancelOrderInput;
      output OrderView;
      fails InconsistentOrder;
      fails NotCancellable;
      fails NotYourOrder;
      fails OrderNotFound;
      fails OrderTooLarge;
      fails StockLimit;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/cancel";
      workflow {
        load PurchaseOrder by input.id as order for update else OrderNotFound;
        validate order.buyer == actor else NotYourOrder;
        update order when order.state == OrderState.CREATED else NotCancellable { state: OrderState.CANCELLED; }
        persist order;
        count OrderLine where item.purchase == order as lineCount;
        validate lineCount > 0 else InconsistentOrder;
        validate lineCount <= 100 else OrderTooLarge;
        each OrderLine where item.purchase == order order by product ascending, id ascending limit 100 else OrderTooLarge as line {
          validate line.quantity > 0 else InconsistentOrder;
          load ShopProduct by line.product as goods for update else InconsistentOrder;
          update goods when goods.stock + line.quantity <= 2147483647 else StockLimit { stock: goods.stock + line.quantity; }
          persist goods;
        }
        each Redemption where item.purchase == order order by id ascending limit 100 else OrderTooLarge as claim {
          load Coupon by claim.coupon as coupon for update else CouponNotFound;
          update coupon { used: coupon.used - 1; }
          persist coupon;
          delete claim;
        }
        return order;
      }
    }

    capability MyOrders {
      actor Ref<User>;
      input MyOrdersInput;
      output Page<OrderView>;
      fails BadPage;
      requires authenticated;
      requires readonly;
      expose query at "/orders";
      workflow {
        find PurchaseOrder where item.buyer == actor order by createdAt descending, id descending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability OrderLines {
      actor Ref<User>;
      input OrderLinesInput;
      output Page<OrderLineView>;
      fails BadPage;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires readonly;
      expose query at "/orders/{orderId}/lines";
      workflow {
        load PurchaseOrder by input.orderId as order else OrderNotFound;
        validate order.buyer == actor else NotYourOrder;
        find OrderLine where item.purchase == order order by id ascending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability Multiply {
      input MultiplyInput;
      output CalculationView;
      requires atomic;
      expose command at "/multiply";
      workflow {
        create Calculation as made { amount: input.price * input.quantity; count: input.left * input.right; wide: input.wide * 2; }
        persist made;
        return made;
      }
    }

    capability Wide {
      input WideInput;
      output CalculationView;
      requires atomic;
      expose command at "/wide";
      workflow {
        create Calculation as made { amount: input.price * input.quantity; count: input.left * input.right; wide: input.wide * 2; }
        persist made;
        return made;
      }
    }

    capability Reverse {
      input ReverseInput;
      output CalculationView;
      requires atomic;
      expose command at "/reverse";
      workflow {
        create Calculation as made { amount: input.price * input.quantity; count: input.left * input.right; wide: input.wide * 2; }
        persist made;
        return made;
      }
    }

    capability PurchaseProduct {
      input PurchaseProductInput;
      output ReceiptView;
      fails OutOfStock;
      fails ProductNotFound;
      requires atomic;
      expose command at "/purchase";
      workflow {
        load Product by input.id as goods for update else ProductNotFound;
        update goods when goods.stock >= input.quantity else OutOfStock { stock: goods.stock - input.quantity; }
        persist goods;
        create Receipt as made { product: goods; total: goods.price * input.quantity; quantity: input.quantity; }
        persist made;
        create ReceiptLine as line { receipt: made; quantity: input.quantity; unitPrice: goods.price; }
        persist line;
        return made;
      }
    }

    capability EnrollCourse {
      input EnrollCourseInput;
      output CourseView;
      fails Full;
      requires atomic;
      expose command at "/courses/enroll";
      workflow {
        load Course by input.id as course for update else Missing;
        update course when course.enrolled < course.capacity else Full { enrolled: course.enrolled + 1; }
        persist course;
        return course;
      }
    }

    capability ShowCourse {
      input ShowCourseInput;
      output CourseView;
      fails Missing;
      requires readonly;
      expose query at "/courses/show";
      workflow {
        load Course by input.id as course else Missing;
        return course;
      }
    }

    capability Book {
      input BookInput;
      output BookingView;
      fails InvalidWindow;
      fails RoomMissing;
      fails SlotTaken;
      requires atomic;
      expose command at "/bookings";
      workflow {
        validate input.startsAt < input.endsAt else InvalidWindow;
        load Room by input.roomId as room for update else RoomMissing;
        exists Booking where item.room == room and item.startsAt < input.endsAt and item.endsAt > input.startsAt as taken;
        validate not taken else SlotTaken;
        create Booking as made { room: room; startsAt: input.startsAt; endsAt: input.endsAt; }
        persist made;
        return made;
      }
    }

    capability BookAfterRead {
      input BookAfterReadInput;
      output BookingView;
      fails InvalidWindow;
      fails RoomMissing;
      fails SlotTaken;
      requires atomic;
      expose command at "/bookings/after-read";
      workflow {
        validate input.startsAt < input.endsAt else InvalidWindow;
        load Room by input.roomId as room else RoomMissing;
        exists Booking where item.room == room and item.startsAt < input.endsAt and item.endsAt > input.startsAt as taken;
        validate not taken else SlotTaken;
        load Room by input.roomId as locked for update else RoomMissing;
        exists Booking where item.room == locked and item.startsAt < input.endsAt and item.endsAt > input.startsAt as takenAgain;
        validate not takenAgain else SlotTaken;
        create Booking as made { room: locked; startsAt: input.startsAt; endsAt: input.endsAt; }
        persist made;
        return made;
      }
    }

    capability BookWeekly {
      input BookWeeklyInput;
      output Unit;
      fails InvalidWindow;
      fails RoomMissing;
      fails SlotTaken;
      fails TooManyWeeks;
      requires atomic;
      expose command at "/bookings/weekly";
      workflow {
        validate input.startsAt < input.endsAt else InvalidWindow;
        validate input.weeks >= 1 else TooManyWeeks;
        validate input.weeks <= 12 else TooManyWeeks;
        load Room by input.roomId as room for update else RoomMissing;
        repeat input.weeks times limit 12 else TooManyWeeks as week {
          exists Booking where item.room == room and item.startsAt < addDays(input.endsAt, week * 7) and item.endsAt > addDays(input.startsAt, week * 7) as taken;
          validate not taken else SlotTaken;
          create Booking as made { room: room; startsAt: addDays(input.startsAt, week * 7); endsAt: addDays(input.endsAt, week * 7); }
          persist made;
        }
        return unit;
      }
    }
  }
}

messages.content:
你为 KCG-Code 生成完整、可静态检查的 SIR 0.3 文档。只返回 SIR 源码，不加 Markdown 围栏、Java、SQL、解释或思维过程。只用下面出现过的写法，不得凭空发明语言构造；拿不准时用已出现的构造组合。

一、文档骨架（固定）
sir 0.3
software 名字 {
  metadata { displayName "名字"; namespace "合同给出的包名"; }
  target { language java 21; framework spring_boot; persistence mybatis_plus; database mysql; build maven; interface rest; }
  sources { }
  imports { }
  declarations { 声明 }
}
保留字不能当实体、字段、变量（as 后面的名字）、错误或能力的名字，最容易撞上的是 item、order、error、input、target、query、command、build、from、field、present；变量可以叫 course、row、made、found。注释用 //。

二、类型
Id（64 位编号）、Serial（64 位整数）、Version（版本号）、Count（32 位整数）、Quantity（至少 1）、PageNo、PageSize、Money（十进制，默认 precision(19, 2)）、Text、Name（非空白，1～100）、Code（非空白，1～32）、Remark、Email、Secret（口令，只存摘要）、Token（UUID）、Moment（时刻，UTC）、Day（日期）、Flag（布尔）、Unit、Optional<T>、List<T>、Page<T>、Ref<实体>。
可自定义：type UnitPrice = Money where precision(19, 4), min(0);
枚举：enum Status { OPEN, CLOSED }，用时写 Status.OPEN。

三、声明
以下是不同软件的片段或语法模板，中文和省略号是占位符，不可原样拼成完整软件。除内置类型或 use 明确展开的声明外，所有引用的实体、input、输出视图、枚举和错误都要声明；实体不会自动带同名 View，视图引用的子视图也要声明。
实体：
entity Course persistent {
  identity id: Id generated auto;
  field code: Code unique;
  field capacity: Quantity;
  field enrolled: Count default 0;
  field note: Optional<Text>;
  field owner: Ref<User>;
}
- 成员顺序固定：identity，所有 field，联合 unique (a, b);（若有），credential（若有），scope（若有）。
- identity 二选一：identity id: Id generated auto; 或 identity id: Token generated uuid;。
- 字段修饰顺序固定：where 约束、versioned、unique、secret、default 值。例如 field name: Name where length(1, 64) unique;。约束有 notBlank、email、timeZone、length(最小, 最大)、min(值)、max(值)、precision(总位数, 小数位)。
- default 可为常量、枚举成员或 now()；create 可省带 default 的字段。unique、secret、versioned 字段不能有 default。
- 软删除：field removed: Flag default false; scope removed == false;。scope 统一限制该实体的 load、find、exists、count、sum/avg、each、any；公开读取也受限，load 到范围外按自己的 else 失败，不能只在列表里过滤而让详情漏出。scope 直接写本实体字段，只描述本行，不能含 any 或 .present。
- 访问令牌实体：identity id: Token generated uuid; field owner: Ref<User>; field expiresAt: Moment; credential subject owner expires expiresAt;。Bearer 令牌就是凭据行主键；认证后 actor 是 subject 字段所指的 User，不是 AccessToken。一个主体只能有一种凭据；同一软件的 authenticated 能力不能混用凭据和非凭据认证。双令牌模式的刷新令牌不要声明 credential。
- 数据库对应：实体名 TokenPair 对应表 token_pair，字段 accessExpiresAt 对应列 access_expires_at，引用字段 owner 对应列 owner_id；须符合输入给出的表结构。
输入：input RegisterInput { field name: Name where length(1, 64); field note: Optional<Text>; }。输入字段只有名字、类型和 where，不能写 default。notBlank、length、min 等约束写在 where（或继承语义类型），不是 validate 表达式；非空白输入可写 field keyword: Text where notBlank;。
普通输入必填：非 Optional 字段一律必填，不论工作流是做比较、算术、直接绑定还是根本没用到；没传或 null，在工作流之前返回 400 INVALID_REQUEST，fields 中为请求字段名（Ref 字段为名字Id）及 NotNull，不能当 0。带 notBlank 的文本（包括 Name、Code）缺值报 NotBlank；Optional<T> 可缺省、可 null。min/max 只检查有值时的范围，不负责必填。只作分页参数的字段例外，见下一条；patch 的 changes 仍保持没传不改，不会全部必填。不需要、也不要为了触发必填而写 input.x - 1 >= 0 这类绕弯运算，不要发明 where notNull 或用 is present 检查普通数值。
分页：field page: PageNo; field size: PageSize;，配 find … Page input.page, input.size else 错误。须用输入里两个不同的直接字段；只作本能力分页参数时，缺失/null 默认页码 1、页大小 20，上限页码 10000、页大小 100，无需自写。若分页字段还参与算术、内置函数或 repeat 次数，则仍必填。同一 input 被另一个不分页的能力使用时，这两个字段在那个能力里照样必填；不按 page/size 名字或 PageNo/PageSize 类型猜默认值。
局部更新（实体须有 Version）：input UpdateCourseInput patch of Course { field id: Id; field name: Text; }。写主键及至少一个允许修改的对应字段，不写 Version；字段不能带规则：Name/Code/Remark/Email 换成 Text，Quantity 换成 Count，可选文本用 Optional<Text>。每个可变字段都直接绑定 name: input.name;，没传自动保留，不能写 ? : 三元表达式。input.name.present 问是否传了可变字段，主键不能 .present；普通 Optional 用 is none/is present。例如 validate input.name.present or input.capacity.present else EmptyChange;。update 后 persist course else StaleVersion;。版本化实体禁 update … when 和本字段原子加减，冲突由 persist … else 处理。PATCH JSON 为 {"id": …, "expectedVersion": …, "changes": { 可改字段 }}，主键名随实体；expectedVersion/changes 是生成的外层，不写进 input。
视图：view CourseView from Course { field id: Id; field code: Code; field remaining: Count = item.capacity - item.enrolled; field owner: UserSummary; field items: List<ItemView>; }。同名字段读实体字段；= 表达式是计算字段，只能用来源行纯标量、常量及允许的函数，不捕获 input/actor/now()。Ref 可对应另一视图，List<子视图> 要有唯一一个子实体 Ref 指回父实体；嵌套最多两层，不可循环。嵌套结果只能来自分页 find 或 load/create 后返回单行；视图不能读 secret，不能带 where 约束。
跨行计数：field availableCopies: Serial = count(Copy, book == item and status == CopyStatus.AVAILABLE);。必须关联子 Ref==item，只用于 readonly query 的输出；不能捕获 input/actor/时钟或沿无界 List 返回。
错误：error NotFound http 404;（默认 400；只允许 400、401、403、404、409）。未登录/无效凭据用 401，已登录无权用 403。

四、能力
capability PublishGoods {
  actor Ref<User>;
  input PublishInput;
  output GoodsView;
  fails GoodsNotFound;
  fails NotSeller;
  requires authenticated;
  requires atomic;
  expose command;
  workflow { 步骤 }
}
- 子句顺序：actor → input → output → fails（错误名升序，每个一行）→ requires（authenticated、atomic、readonly 顺序）→ expose → workflow。
- output 可为视图、Ref<实体>、List<Ref<实体>>、Page<视图>、Page<SumGroup<Ref<实体>>>、Unit 或值类型；工作流的每个错误都要写进当前能力的 fails。
- authenticated 配 actor Ref<主体实体>;，是否要求认证按合同，不因输入含令牌就自行添加。两个及以上写步骤（create/update/persist/delete）须 atomic；query 须 readonly 且不能写库，atomic 与 readonly 互斥。
- 路由：query 默认 GET /api/能力名短横线形式；command 默认 POST，patch 输入固定 PATCH，不能另指定 put/delete。GET/DELETE 用查询参数，POST/PUT/PATCH 用 JSON；路径字段覆盖同名输入后再校验。command 可接 put、delete 或 at，不能写 post。例：expose query at "/notes/{id}"; expose command at "/notes"; expose command put at "/notes/{id}"; expose command delete at "/notes/{id}";。路径自动加 /api，勿重复；默认路由合同时可省 at。路径参数须对应直接必填标量，patch 仅主键可入路径；方法+路径形状不能重复。
- 成功码：工作流含 create（包括循环体）则 201，否则 200；要求 200 的接口不能 create，要求 201 要实际新建，不能改成 query 来改状态码。

五、工作流（按顺序执行，以且只以一个 return 结束）
validate 条件 else 错误;
load 实体 by input.id as 变量 else 错误;（主键不写字段名，不能写 by id: …）
load 实体 by 唯一字段名: input.name as 变量 else 错误;（该字段须声明 unique；版本化实体要更新时按主键加载）
load 实体 by input.id as 变量 for update else 错误;（仅 atomic command 按主键；锁到事务结束）
find 实体 where item.字段 >= input.x and item.title containsLiteral input.keyword order by 字段 descending, id ascending Page input.page, input.size else BadPage as 变量;
- find、exists、count（及 sum/avg、each）条件内，item 是当前查询根行；普通比较左边为 item.直接字段，右边不读 item，不写裸字段或自比较，也不沿 item.ref.otherField 隐式连接。不对列做运算，请求侧运算可作参数。不带 Page 得 List<Ref<实体>>，带 Page 得 Page<视图> 且用于 query；where true 仍受 scope 限制。
- Optional 筛选：input.kind is none or item.kind == input.kind；归属筛选：item.owner == actor。
- any 内裸字段属于被查的关联实体，item 仍是外层根行；例如 any(Enrollment, course == item and status == EnrollmentStatus.ACTIVE)。最外层 and 中必须有两种连接之一：关联实体的 Ref 字段 == item，或关联实体的主键 == item.引用字段，等号可交换。反向例：any(Category, id == item.category and owner == actor)。不可嵌套 any、任意跨表列比较或隐式多表 JOIN。需按另一实体的字段筛选时，以它为查询根，再用 any 关联；要求同一关联行满足的条件放在同一个 any，所需状态/归属条件不能丢。
create 实体 as 变量 { 字段: 值; ... }（所有必填字段，不绑主键/Version；Optional/default 可省）
update 变量 { 字段: 值; }
persist 变量;（create/update 后才写库；persist 变量 else 错误; 仅版本化局部更新冲突或新行 unique 冲突；其他情况含守卫更新后均不加 else）
update 变量 when 条件 else 错误 { 字段: 值; }（守卫：在数据库写入时检查条件，后面须 persist；不是所有并发请求必有唯一赢家，只有更新后使条件失效的状态转换才是一次性成功。限已加载的非版本行，同一行只能有一个 update；未锁定时绑定不能读本行其他字段，先 for update 锁住目标后可读，另允许本字段原子加减）
计数原子加减：update course when course.enrolled < course.capacity else Full { enrolled: course.enrolled + 1; }。只要每次写时仍有容量，多次成功是正常结果。
delete 变量;（只删 load/each 的行，直接删除，不再 persist）
exists 实体 where 条件 as 布尔;　count 实体 where 条件 as 数量;（结果分别为 Flag、Serial，item 只在条件内有效）
sum 实体.金额字段 where 条件 as 合计;（仅 readonly query，avg 同理；空集合为 0）
sum 实体.金额字段 by 引用字段 where 条件 Page input.page, input.size else BadPage as 分组;（输出 Page<SumGroup<Ref<实体>>>，total 是组数）
month input.month in input.zone as since, until else BadPeriod;（仅 readonly query；严格 YYYY-MM 和区域时区，得当地自然月转 UTC 的半开起止时刻）
each 实体 where 条件 order by 字段 ascending, id ascending limit 50 else TooMany as 行 { 步骤 }（仅 atomic command；limit 为 1～100 字面量，排序主键收尾；超限一次不执行。体内禁 find/return/嵌套循环/聚合/month；循环外行仅可无守卫本字段累加）
repeat input.weeks times limit 12 else TooMany as week { 步骤 }（仅 atomic command，次数须非可选 Count 类整数，缺值按 NotNull 拒绝；序号从 0 起，体内限制同 each）
return 变量;（或 return unit;）

六、易错点
自查：名字不撞保留字；create 不绑 Version；persist else 仅上述两类；每个 else 错误列入当前 fails。
- 新行 persist 前没有主键：先 persist access; 再读 access.id、把 access 当引用值或返回含主键的视图（SIR-FLOW-007）；其他字段 create 后即可读。
- 新建引用行且修改父行，先 persist 父行再 persist 新行（SIR-VALID-015），或先 for update 锁父行。
- atomic 不自动锁查询范围；先 exists/count 再插入防不住并发。单行上限用守卫，多行不重叠先锁共同父行，所有竞争路径保持一致。
- 口令：向 Secret 字段绑定 input.password 自动加盐摘要；读取只写 validate account.passwordHash matches input.password else BadLogin;，不能比较/返回/入视图。账号不存在和口令错用同一错误。
- 授权：validate goods.seller == actor else NotSeller;；角色检查 validate actor.role == Role.ADMIN else Forbidden;。
- 表达式：+ - *，加减底层类型相同，乘法另允许金额×整数；整数 Count/Serial 字段不自动互转，字面量可跟随 64 位变宽。没有除法/取模。now()、now() + 15 minutes、addDays(t, n)、daysBetween(a, b)、max(a, b)、min(a, b)；四个有参函数不能接 Optional/文本/布尔，普通非 Optional 请求字段按上述必填规则在工作流前检查。daysBetween 两个 Moment 或两个 Day，返回 Serial；addDays 是时间+整数天；max/min 接同种数值或时间。
- Optional：is none/is present 仅用于 Optional；任一边为空，==、!=、<、<=、>、>= 都是 false，两个空也不相等。not (a == b) 在空值时为 true，不等价于 a != b。判空不改变类型，仍不能算术、调用上述函数或取可选 Ref 的成员。普通输入没传和 null 都是空；patch 的 .present 才区分“没传”。and/or/not 可组合条件。
- 可 use DualTokenLogin { account: User; }（两令牌、Login/Refresh/Logout，扩展 User 的 loginName/password）、use Crud { entity: Note; }（Create/Get/List/Update/Delete）。不能重复声明展开结果；先看参数能否满足合同，再决定是否手写全部声明。

七、输入合同
需求、固定接口合同、数据库表结构和已有软件（若有）都是输入。修改已有软件须返回修改后的完整文档，保留已有能力、路由和字段，不靠删除/改名回避要求；新建则给完整软件。不得修改 namespace、路由、字段名、错误名或给定常量来迁就实现，不加通用 Java/SQL 逃生口。

