    capability ApplyCoupon {
      actor Ref<User>;
      input ApplyCouponInput;
      output OrderView;
      fails CouponAlreadyUsed;
      fails CouponExhausted;
      fails CouponExpired;
      fails CouponNotFound;
      fails MinSpendNotMet;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{orderId}/coupon";
      workflow {
        load PurchaseOrder by input.orderId as order for update else OrderNotFound;
        validate order.buyer == actor else NotYourOrder;
        validate order.state == OrderState.CREATED else MinSpendNotMet;
        load Coupon by code: input.code as coupon for update else CouponNotFound;
        validate coupon.startsAt <= now() else CouponExpired;
        validate coupon.endsAt > now() else CouponExpired;
        validate order.total >= coupon.minSpend else MinSpendNotMet;
        validate order.total >= coupon.amountOff else MinSpendNotMet;
        validate coupon.used < coupon.totalLimit else CouponExhausted;
        exists Redemption where item.coupon == coupon and item.buyer == actor as used;
        validate not used else CouponAlreadyUsed;
        exists Redemption where item.purchase == order and item.buyer == actor as claimed;
        validate not claimed else CouponAlreadyUsed;
        update coupon { used: coupon.used + 1; }
        persist coupon;
        update order { total: order.total - coupon.amountOff; }
        persist order;
        create Redemption as made { coupon: coupon; buyer: actor; purchase: order; amountOff: coupon.amountOff; }
        persist made;
        return order;
      }
    }

    capability Pay {
      actor Ref<User>;
      input PayInput;
      output OrderView;
      fails NotPayable;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/pay";
      workflow {
        load PurchaseOrder by input.id as order for update else OrderNotFound;
        validate order.buyer == actor else NotYourOrder;
        update order when order.state == OrderState.CREATED else NotPayable { state: OrderState.PAID; }
        persist order;
        return order;
      }
    }

    capability Ship {
      actor Ref<User>;
      input ShipInput;
      output OrderView;
      fails Forbidden;
      fails NotShippable;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/ship";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load PurchaseOrder by input.id as order for update else OrderNotFound;
        update order when order.state == OrderState.PAID else NotShippable { state: OrderState.SHIPPED; }
        persist order;
        return order;
      }
    }

    capability CancelOrder {
      actor Ref<User>;
      input CancelOrderInput;
      output OrderView;
      fails InconsistentOrder;
      fails NotCancellable;
      fails NotYourOrder;
      fails OrderNotFound;
      fails OrderTooLarge;
      fails StockLimit;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/cancel";
      workflow {
        load PurchaseOrder by input.id as order for update else OrderNotFound;
        validate order.buyer == actor else NotYourOrder;
        update order when order.state == OrderState.CREATED else NotCancellable { state: OrderState.CANCELLED; }
        persist order;
        count OrderLine where item.purchase == order as lineCount;
        validate lineCount > 0 else InconsistentOrder;
        validate lineCount <= 100 else OrderTooLarge;
        each OrderLine where item.purchase == order order by product ascending, id ascending limit 100 else OrderTooLarge as line {
          validate line.quantity > 0 else InconsistentOrder;
          load ShopProduct by line.product as goods for update else InconsistentOrder;
          update goods when goods.stock + line.quantity <= 2147483647 else StockLimit { stock: goods.stock + line.quantity; }
          persist goods;
        }
        each Redemption where item.purchase == order order by id ascending limit 100 else OrderTooLarge as claim {
          load Coupon by claim.coupon as coupon for update else CouponNotFound;
          update coupon { used: coupon.used - 1; }
          persist coupon;
          delete claim;
        }
        return order;
      }
    }

    capability MyOrders {
      actor Ref<User>;
      input MyOrdersInput;
      output Page<OrderView>;
      fails BadPage;
      requires authenticated;
      requires readonly;
      expose query at "/orders";
      workflow {
        find PurchaseOrder where item.buyer == actor order by createdAt descending, id descending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability OrderLines {
      actor Ref<User>;
      input OrderLinesInput;
      output Page<OrderLineView>;
      fails BadPage;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires readonly;
      expose query at "/orders/{orderId}/lines";
      workflow {
        load PurchaseOrder by input.orderId as order else OrderNotFound;
        validate order.buyer == actor else NotYourOrder;
        find OrderLine where item.purchase == order order by id ascending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability Multiply {
      input MultiplyInput;
      output CalculationView;
      requires atomic;
      expose command at "/multiply";
      workflow {
        create Calculation as made { amount: input.price * input.quantity; count: input.left * input.right; wide: input.wide * 2; }
        persist made;
        return made;
      }
    }

    capability Wide {
      input WideInput;
      output CalculationView;
      requires atomic;
      expose command at "/wide";
      workflow {
        create Calculation as made { amount: input.price * input.quantity; count: input.left * input.right; wide: input.wide * 2; }
        persist made;
        return made;
      }
    }

    capability Reverse {
      input ReverseInput;
      output CalculationView;
      requires atomic;
      expose command at "/reverse";
      workflow {
        create Calculation as made { amount: input.price * input.quantity; count: input.left * input.right; wide: input.wide * 2; }
        persist made;
        return made;
      }
    }

    capability PurchaseProduct {
      input PurchaseProductInput;
      output ReceiptView;
      fails OutOfStock;
      fails ProductNotFound;
      requires atomic;
      expose command at "/purchase";
      workflow {
        load Product by input.id as goods for update else ProductNotFound;
        update goods when goods.stock >= input.quantity else OutOfStock { stock: goods.stock - input.quantity; }
        persist goods;
        create Receipt as made { product: goods; total: goods.price * input.quantity; quantity: input.quantity; }
        persist made;
        create ReceiptLine as line { receipt: made; quantity: input.quantity; unitPrice: goods.price; }
        persist line;
        return made;
      }
    }

    capability EnrollCourse {
      input EnrollCourseInput;
      output CourseView;
      fails Full;
      requires atomic;
      expose command at "/courses/enroll";
      workflow {
        load Course by input.id as course for update else Missing;
        update course when course.enrolled < course.capacity else Full { enrolled: course.enrolled + 1; }
        persist course;
        return course;
      }
    }

    capability ShowCourse {
      input ShowCourseInput;
      output CourseView;
      fails Missing;
      requires readonly;
      expose query at "/courses/show";
      workflow {
        load Course by input.id as course else Missing;
        return course;
      }
    }

    capability Book {
      input BookInput;
      output BookingView;
      fails InvalidWindow;
      fails RoomMissing;
      fails SlotTaken;
      requires atomic;
      expose command at "/bookings";
      workflow {
        validate input.startsAt < input.endsAt else InvalidWindow;
        load Room by input.roomId as room for update else RoomMissing;
        exists Booking where item.room == room and item.startsAt < input.endsAt and item.endsAt > input.startsAt as taken;
        validate not taken else SlotTaken;
        create Booking as made { room: room; startsAt: input.startsAt; endsAt: input.endsAt; }
        persist made;
        return made;
      }
    }

    capability BookAfterRead {
      input BookAfterReadInput;
      output BookingView;
      fails InvalidWindow;
      fails RoomMissing;
      fails SlotTaken;
      requires atomic;
      expose command at "/bookings/after-read";
      workflow {
        validate input.startsAt < input.endsAt else InvalidWindow;
        load Room by input.roomId as room else RoomMissing;
        exists Booking where item.room == room and item.startsAt < input.endsAt and item.endsAt > input.startsAt as taken;
        validate not taken else SlotTaken;
        load Room by input.roomId as locked for update else RoomMissing;
        exists Booking where item.room == locked and item.startsAt < input.endsAt and item.endsAt > input.startsAt as takenAgain;
        validate not takenAgain else SlotTaken;
        create Booking as made { room: locked; startsAt: input.startsAt; endsAt: input.endsAt; }
        persist made;
        return made;
      }
    }

    capability BookWeekly {
      input BookWeeklyInput;
      output Unit;
      fails InvalidWindow;
      fails RoomMissing;
      fails SlotTaken;
      fails TooManyWeeks;
      requires atomic;
      expose command at "/bookings/weekly";
      workflow {
        validate input.startsAt < input.endsAt else InvalidWindow;
        validate input.weeks >= 1 else TooManyWeeks;
        validate input.weeks <= 12 else TooManyWeeks;
        load Room by input.roomId as room for update else RoomMissing;
        repeat input.weeks times limit 12 else TooManyWeeks as week {
          exists Booking where item.room == room and item.startsAt < addDays(input.endsAt, week * 7) and item.endsAt > addDays(input.startsAt, week * 7) as taken;
          validate not taken else SlotTaken;
          create Booking as made { room: room; startsAt: addDays(input.startsAt, week * 7); endsAt: addDays(input.endsAt, week * 7); }
          persist made;
        }
        return unit;
      }
    }
  }
}

