      field startsAt: Moment;
      field endsAt: Moment;
    }

    input RegisterInput {
      field name: Name where length(1, 64);
      field password: Secret;
    }

    input LoginInput {
      field name: Name where length(1, 64);
      field password: Secret;
    }

    input RefreshInput {
      field refreshToken: Token;
    }

    input LogoutInput {
      field refreshToken: Token;
    }

    input AddProductInput {
      field name: Name where length(1, 64);
      field description: Optional<Text>;
      field price: TotalAmount;
