      field minSpend: TotalAmount;
      field startsAt: Moment;
      field endsAt: Moment;
      field totalLimit: Count;
    }

    input ApplyCouponInput {
      field orderId: Id;
      field code: Code where length(1, 64);
    }

    input PayInput {
      field id: Id;
    }

    input ShipInput {
      field id: Id;
    }

    input CancelOrderInput {
      field id: Id;
    }

    input MyOrdersInput {
      field page: PageNo;
      field size: PageSize;
    }

    input OrderLinesInput {
      field orderId: Id;
      field page: PageNo;
      field size: PageSize;
    }

    input MultiplyInput {
      field price: UnitPrice;
      field quantity: Count;
      field left: Count;
      field right: Count;
      field wide: Serial;
    }

    input WideInput {
      field price: UnitPrice;
      field quantity: Count;
      field left: Count;
      field right: Count;
      field wide: Serial;
    }

    input ReverseInput {
      field price: UnitPrice;
      field quantity: Count;
      field left: Count;
      field right: Count;
      field wide: Serial;
    }

    input PurchaseProductInput {
      field id: Id;
      field quantity: Quantity;
    }

    input EnrollCourseInput {
      field id: Id;
    }

    input ShowCourseInput {
      field id: Id;
    }

    input ShowProductInput {
      field id: Id;
    }

    input BookInput {
      field roomId: Id;
      field startsAt: Moment;
      field endsAt: Moment;
    }

    input BookWeeklyInput {
      field roomId: Id;
      field startsAt: Moment;
      field endsAt: Moment;
      field weeks: Count;
    }

    input BookAfterReadInput {
      field roomId: Id;
      field startsAt: Moment;
      field endsAt: Moment;
    }

    view UserView from User {
      field id: Id;
      field name: Name;
      field role: Role;
    }

    view ShopProductView from ShopProduct {
      field id: Id;
      field name: Name;
      field description: Optional<Text>;
      field price: TotalAmount;
      field stock: Count;
      field state: ProductState;
    }

    view ShopProductShowView from ShopProduct {
      field id: Id;
      field price: TotalAmount;
      field stock: Count;
      field inventoryValue: UnitPrice = item.price * item.stock;
      field soldOut: Flag = item.stock == 0;
    }

    view OrderView from PurchaseOrder {
      field id: Id;
      field state: OrderState;
      field total: TotalAmount;
      field createdAt: Moment;
    }

    view OrderLineView from OrderLine {
      field id: Id;
      field product: Ref<ShopProduct>;
      field quantity: Quantity;
      field unitPrice: TotalAmount;
    }

    view CartItemView from CartItem {
      field id: Id;
      field product: Ref<ShopProduct>;
      field quantity: Quantity;
    }

    view CouponView from Coupon {
      field id: Id;
      field code: Code;
      field amountOff: TotalAmount;
      field minSpend: TotalAmount;
      field startsAt: Moment;
      field endsAt: Moment;
      field totalLimit: Count;
      field used: Count;
    }

    view CalculationView from Calculation {
      field id: Id;
      field amount: TotalAmount;
      field count: Count;
      field wide: Serial;
    }

    view ReceiptView from Receipt {
