    }

    view CourseView from Course {
      field id: Id;
      field capacity: Quantity;
      field enrolled: Count;
      field remaining: Count = item.capacity - item.enrolled;
      field full: Flag = item.capacity - item.enrolled == 0;
    }

    view BookingView from Booking {
      field id: Id;
      field startsAt: Moment;
      field endsAt: Moment;
    }

    capability Register {
      input RegisterInput;
      output UserView;
      fails Missing;
      requires atomic;
      expose command at "/register";
      workflow {
        validate input.name is present else Missing;
        exists User where item.name == input.name as found;
        validate not found else Missing;
        create User as made { name: input.name; passwordHash: input.password; role: Role.CUSTOMER; }
        persist made;
        return made;
      }
    }

    capability Login {
      input LoginInput;
      output TokenPair;
      fails Missing;
      requires atomic;
      expose command at "/login";
      workflow {
        load User by name: input.name as account else Missing;
        validate account.passwordHash matches input.password else Missing;
        create AccessToken as access { owner: account; expiresAt: now() + 15 minutes; }
        persist access;
        create RefreshToken as refresh { owner: account; used: false; expiresAt: now() + 7 days; }
        persist refresh;
        create TokenPair as pair { accessToken: access.id; accessExpiresAt: access.expiresAt; refreshToken: refresh.id; refreshExpiresAt: refresh.expiresAt; }
        persist pair;
        return pair;
      }
    }

    capability Refresh {
      input RefreshInput;
      output TokenPair;
      fails Missing;
      requires atomic;
      expose command at "/refresh";
      workflow {
        load RefreshToken by input.refreshToken as stored else Missing;
        validate stored.used == false else Missing;
        validate stored.expiresAt > now() else Missing;
        update stored { used: true; }
        persist stored;
        create AccessToken as access { owner: stored.owner; expiresAt: now() + 15 minutes; }
        persist access;
        create RefreshToken as refresh { owner: stored.owner; used: false; expiresAt: now() + 7 days; }
        persist refresh;
        create TokenPair as pair { accessToken: access.id; accessExpiresAt: access.expiresAt; refreshToken: refresh.id; refreshExpiresAt: refresh.expiresAt; }
        persist pair;
        return pair;
      }
    }

    capability Logout {
      input LogoutInput;
      output Unit;
      fails Missing;
      requires atomic;
      expose command at "/logout";
      workflow {
        load RefreshToken by input.refreshToken as stored else Missing;
        delete stored;
        return unit;
      }
    }

    capability AddProduct {
      actor Ref<User>;
      input AddProductInput;
      output ShopProductView;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command at "/products";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        create ShopProduct as made { name: input.name; description: input.description; price: input.price; stock: input.stock; state: ProductState.ON_SHELF; }
        persist made;
        return made;
      }
    }

    capability SearchProducts {
      input SearchProductsInput;
      output Page<ShopProductView>;
      fails BadPage;
      requires readonly;
      expose query at "/products";
      workflow {
        find ShopProduct where item.state == ProductState.ON_SHELF and item.name containsLiteral input.keyword order by name ascending, id ascending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability ShowProduct {
      input ShowProductInput;
      output ShopProductShowView;
      fails ProductNotFound;
      requires readonly;
      expose query at "/products/show";
      workflow {
        load ShopProduct by input.id as found else ProductNotFound;
        return found;
      }
    }

    capability BuyNow {
      actor Ref<User>;
      input BuyNowInput;
      output OrderView;
      fails OutOfStock;
      fails ProductNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders";
      workflow {
        load ShopProduct by input.productId as goods for update else ProductNotFound;
        validate goods.state == ProductState.ON_SHELF else ProductNotFound;
        update goods when goods.stock >= input.quantity else OutOfStock { stock: goods.stock - input.quantity; }
        persist goods;
        create PurchaseOrder as made { buyer: actor; state: OrderState.CREATED; total: goods.price * input.quantity; createdAt: now(); }
        persist made;
        create OrderLine as line { purchase: made; product: goods; quantity: input.quantity; unitPrice: goods.price; }
        persist line;
        return made;
      }
    }

    capability AddToCart {
      actor Ref<User>;
      input AddToCartInput;
      output CartItemView;
      fails AlreadyInCart;
      fails ProductNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/cart";
      workflow {
        load ShopProduct by input.productId as goods else ProductNotFound;
        validate goods.state == ProductState.ON_SHELF else ProductNotFound;
        exists CartItem where item.owner == actor and item.product == goods as found;
        validate not found else AlreadyInCart;
        create CartItem as made { owner: actor; product: goods; quantity: input.quantity; }
        persist made;
        return made;
      }
    }

    capability ChangeCartQuantity {
      actor Ref<User>;
      input ChangeCartQuantityInput;
      output CartItemView;
      fails CartItemNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/cart/{id}/quantity";
      workflow {
        load CartItem by input.id as row else CartItemNotFound;
        validate row.owner == actor else CartItemNotFound;
        update row { quantity: input.quantity; }
        persist row;
        return row;
      }
    }

    capability RemoveFromCart {
      actor Ref<User>;
      input RemoveFromCartInput;
      output Unit;
      fails CartItemNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/cart/{id}/remove";
      workflow {
        load CartItem by input.id as row else CartItemNotFound;
        validate row.owner == actor else CartItemNotFound;
        delete row;
        return unit;
      }
    }

    capability MyCart {
      actor Ref<User>;
      input MyCartInput;
      output Page<CartItemView>;
      fails BadPage;
      requires authenticated;
      requires readonly;
      expose query at "/cart";
      workflow {
        find CartItem where item.owner == actor order by id ascending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability ClearCart {
      actor Ref<User>;
      input ClearCartInput;
      output Unit;
      requires authenticated;
      requires atomic;
      expose command at "/cart/clear";
      workflow {
        each CartItem where item.owner == actor order by id ascending limit 100 else CartTooLarge as row {
          delete row;
        }
        return unit;
      }
    }

    capability Checkout {
      actor Ref<User>;
      input CheckoutInput;
      output OrderView;
      fails CartEmpty;
      fails CartTooLarge;
      fails OutOfStock;
      requires authenticated;
      requires atomic;
      expose command at "/cart/checkout";
      workflow {
        count CartItem where item.owner == actor as total;
        validate total > 0 else CartEmpty;
        validate total <= 50 else CartTooLarge;
        create PurchaseOrder as made { buyer: actor; state: OrderState.CREATED; total: 0.00; createdAt: now(); }
        persist made;
        each CartItem where item.owner == actor order by id ascending limit 50 else CartTooLarge as row {
          load ShopProduct by row.product as goods for update else ProductNotFound;
          validate goods.state == ProductState.ON_SHELF else ProductNotFound;
          update goods when goods.stock >= row.quantity else OutOfStock { stock: goods.stock - row.quantity; }
          persist goods;
          create OrderLine as line { purchase: made; product: goods; quantity: row.quantity; unitPrice: goods.price; }
          persist line;
          update made { total: made.total + goods.price * row.quantity; }
          delete row;
        }
        persist made;
        return made;
      }
    }

    capability AddCoupon {
      actor Ref<User>;
      input AddCouponInput;
      output CouponView;
      fails CouponCodeTaken;
      fails Forbidden;
      fails InvalidWindow;
      requires authenticated;
      requires atomic;
      expose command at "/coupons";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        validate input.startsAt < input.endsAt else InvalidWindow;
        exists Coupon where item.code == input.code as found;
        validate not found else CouponCodeTaken;
        create Coupon as made { code: input.code; amountOff: input.amountOff; minSpend: input.minSpend; startsAt: input.startsAt; endsAt: input.endsAt; totalLimit: input.totalLimit; used: 0; }
        persist made;
        return made;
      }
    }

    capability ApplyCoupon {
      actor Ref<User>;
      input ApplyCouponInput;
      output OrderView;
      fails CouponAlreadyUsed;
      fails CouponExhausted;
      fails CouponExpired;
      fails CouponNotFound;
      fails MinSpendNotMet;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{orderId}/coupon";
      workflow {
        load PurchaseOrder by input.orderId as orderRow for update else OrderNotFound;
        validate orderRow.buyer == actor else NotYourOrder;
        validate orderRow.state == OrderState.CREATED else MinSpendNotMet;
        load Coupon by code: input.code as coupon for update else CouponNotFound;
        validate coupon.startsAt <= now() else CouponExpired;
        validate coupon.endsAt > now() else CouponExpired;
        validate orderRow.total >= coupon.minSpend else MinSpendNotMet;
        validate orderRow.total >= coupon.amountOff else MinSpendNotMet;
        validate coupon.used < coupon.totalLimit else CouponExhausted;
        exists Redemption where item.coupon == coupon and item.buyer == actor as used;
        validate not used else CouponAlreadyUsed;
        exists Redemption where item.purchase == orderRow and item.buyer == actor as claimed;
        validate not claimed else CouponAlreadyUsed;
        update coupon { used: coupon.used + 1; }
        persist coupon;
        update orderRow { total: orderRow.total - coupon.amountOff; }
        persist orderRow;
        create Redemption as made { coupon: coupon; buyer: actor; purchase: orderRow; amountOff: coupon.amountOff; }
        persist made;
        return orderRow;
      }
    }

    capability Pay {
      actor Ref<User>;
      input PayInput;
      output OrderView;
      fails NotPayable;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/pay";
      workflow {
        load PurchaseOrder by input.id as orderRow for update else OrderNotFound;
        validate orderRow.buyer == actor else NotYourOrder;
        update orderRow when orderRow.state == OrderState.CREATED else NotPayable { state: OrderState.PAID; }
        persist orderRow;
        return orderRow;
      }
    }

    capability Ship {
      actor Ref<User>;
      input ShipInput;
      output OrderView;
      fails Forbidden;
      fails NotShippable;
      fails OrderNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/ship";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load PurchaseOrder by input.id as orderRow for update else OrderNotFound;
        update orderRow when orderRow.state == OrderState.PAID else NotShippable { state: OrderState.SHIPPED; }
        persist orderRow;
        return orderRow;
      }
    }

    capability CancelOrder {
      actor Ref<User>;
      input CancelOrderInput;
      output OrderView;
      fails InconsistentOrder;
      fails NotCancellable;
      fails NotYourOrder;
      fails OrderNotFound;
      fails OrderTooLarge;
      fails StockLimit;
      requires authenticated;
      requires atomic;
      expose command at "/orders/{id}/cancel";
      workflow {
        load PurchaseOrder by input.id as orderRow for update else OrderNotFound;
        validate orderRow.buyer == actor else NotYourOrder;
        update orderRow when orderRow.state == OrderState.CREATED else NotCancellable { state: OrderState.CANCELLED; }
        persist orderRow;
        count OrderLine where item.purchase == orderRow as lineCount;
        validate lineCount > 0 else InconsistentOrder;
        validate lineCount <= 100 else OrderTooLarge;
        each OrderLine where item.purchase == orderRow order by product ascending, id ascending limit 100 else OrderTooLarge as line {
          validate line.quantity > 0 else InconsistentOrder;
          load ShopProduct by line.product as goods for update else InconsistentOrder;
          update goods when goods.stock + line.quantity <= 2147483647 else StockLimit { stock: goods.stock + line.quantity; }
          persist goods;
        }
        each Redemption where item.purchase == orderRow order by id ascending limit 100 else OrderTooLarge as claim {
          load Coupon by claim.coupon as coupon for update else CouponNotFound;
          update coupon { used: coupon.used - 1; }
          persist coupon;
          delete claim;
        }
        return orderRow;
      }
    }

    capability MyOrders {
      actor Ref<User>;
      input MyOrdersInput;
      output Page<OrderView>;
      fails BadPage;
      requires authenticated;
      requires readonly;
      expose query at "/orders";
      workflow {
        find PurchaseOrder where item.buyer == actor order by createdAt descending, id descending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability OrderLines {
      actor Ref<User>;
      input OrderLinesInput;
      output Page<OrderLineView>;
      fails BadPage;
      fails NotYourOrder;
      fails OrderNotFound;
      requires authenticated;
      requires readonly;
      expose query at "/orders/{orderId}/lines";
      workflow {
        load PurchaseOrder by input.orderId as orderRow else OrderNotFound;
        validate orderRow.buyer == actor else NotYourOrder;
        find OrderLine where item.purchase == orderRow order by id ascending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

